"""Gera os dados fictícios; não executado automaticamente pelo assistente."""
import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'kit'
POLICIES = {
 'trocas': ('Troca e devolução', '''RN01: Arrependimento pode ser solicitado até 7 dias corridos após a entrega. Defeito pode ser informado até 30 dias corridos após a entrega. O dia da entrega é o dia zero; o sétimo e o trigésimo dia estão incluídos. Ração ou areia com embalagem aberta só é trocada em caso de defeito. Portanto, embalagem aberta desses produtos impede troca por arrependimento, mesmo dentro de sete dias. Outros produtos seguem os prazos gerais. Fora desses prazos, o assistente não promete aprovação e oferece atendimento humano para análise. Uma solicitação não significa que uma troca já foi executada. Informe número do pedido, motivo e condição da embalagem; não envie documentos pessoais no chat. O prazo considera a data de entrega registrada no pedido consultado e a data atual da sessão. Para defeito, descreva o problema sem expor dados sensíveis. A equipe informa como enviar fotos do item por canal apropriado. Se houver risco à saúde animal, interrompa o uso e procure orientação veterinária; o atendimento comercial não realiza diagnóstico. A devolução, quando aplicável, é orientada pelo atendimento. O reembolso segue exclusivamente a política de reembolso, sem promessa de crédito ou cupom.'''),
 'reembolso': ('Reembolso', '''RN02: O reembolso ocorre sempre no meio de pagamento original. Em compras pagas por Pix, o prazo é de até 5 dias úteis. Em cartão, o estorno ocorre em até 2 faturas. Não é permitido converter um reembolso de cartão em Pix, nem trocar o destinatário do pagamento. O prazo começa após a aprovação do reembolso pelo atendimento. Dias úteis excluem finais de semana e feriados aplicáveis; este protótipo informa o prazo e não calcula o calendário bancário de feriados. A aprovação depende do fluxo de cancelamento ou devolução aplicável. O assistente pode explicar as condições e consultar um pedido, mas não movimenta valores, não aprova pagamentos e não confirma um estorno sem evidência. Para acompanhar, informe o número do pedido. Não forneça senha bancária, código de autenticação, número completo de cartão ou chave privada. A equipe nunca solicita esses dados para explicar o processo. Se duas faturas passarem sem o lançamento, solicite atendimento humano pelo canal documentado. Valores e prazos não são substituídos por ofertas de desconto. A solicitação é registrada apenas pela equipe responsável, pois este ambiente demonstra consultas e orientações sem efetivar transações.'''),
 'frete': ('Frete e entrega', '''RN03: O frete grátis vale para compras acima de R$ 149 no Sul e Sudeste e acima de R$ 249 nas demais regiões do Brasil. Acima significa estritamente maior: R$ 149,00 no Sul não recebe frete grátis; R$ 149,01 recebe. Nas demais regiões, R$ 249,00 não recebe e R$ 249,01 recebe. As regiões Norte, Nordeste e Centro-Oeste usam o segundo limite. O valor considerado é o subtotal dos produtos depois de descontos e antes do próprio frete. A região de entrega deve estar informada; sem ela, o assistente apresenta as duas condições ou pede a região. Abaixo ou no limite, o valor do frete precisa ser consultado no checkout; não há tabela de preço de frete no kit. O assistente não inventa valor de transporte nem data de entrega. Para pedido já existente, o status disponível pode ser consultado pelo número, respeitando o cliente autenticado da sessão. Este ambiente não contém integração com transportadora nem previsão em tempo real. A gratuidade não altera o direito de devolução. A retirada em loja segue sua política própria e não deve ser confundida com entrega em domicílio.'''),
 'cancelamento': ('Cancelamento de pedido', '''RN04: O cancelamento é permitido somente antes do status Enviado. Pedidos Pago e Em separação ainda estão nessa etapa. Pedidos Enviado e Entregue devem seguir o fluxo de devolução da RN01. Um pedido Cancelado já está encerrado e não pode ser cancelado novamente. O assistente consulta o estado atual antes de informar a elegibilidade; não basta o cliente dizer que o pacote ainda não chegou. Se a consulta falhar, não há confirmação de cancelamento e o atendimento pode ajudar. A orientação de elegibilidade não executa alteração no pedido. O protótipo possui apenas ferramenta de consulta, sem ferramenta para cancelar, cobrar ou movimentar estoque. Para solicitar a execução, use o atendimento humano. Caso o número do pedido esteja ausente, o assistente deve pedi-lo. A consulta exige que o pedido pertença ao cliente da sessão, que não pode ser alterado por uma mensagem no chat. Um pedido de outro cliente é recusado sem mostrar seus itens ou dados. Quando um cancelamento é aprovado pelo atendimento, qualquer reembolso segue o meio de pagamento original e os prazos da política de reembolso. Depois do envio, não prometemos interceptação da transportadora.'''),
 'assinatura': ('Assinatura recorrente', '''A assinatura fictícia permite programar uma nova compra de produtos a cada 30 ou 60 dias. A adesão é opcional e não muda pedidos já enviados. O cliente pode pausar ou encerrar futuras recorrências pelo atendimento antes da criação da próxima compra. Se um pedido da assinatura já foi criado, o cancelamento desse pedido segue a RN04: apenas antes de Enviado. Encerrar uma assinatura não cancela automaticamente pedidos existentes. Cada recorrência depende de disponibilidade do produto, preço confirmado no momento da compra e aprovação do pagamento. Não prometemos estoque reservado nem desconto permanente. A elegibilidade de frete grátis segue a RN03 em cada novo pedido, considerando região e subtotal daquela compra. O assistente pode explicar as regras, mas não cria ou modifica uma assinatura neste protótipo. Para efetuar uma mudança, peça atendimento humano e informe apenas os dados necessários pelo canal oficial fictício. Não envie senhas ou documentos pessoais no chat. Trocas de produtos recebidos seguem a RN01, inclusive as restrições de ração e areia com embalagem aberta. O reembolso, quando aprovado, segue a RN02. O kit não contém histórico ou identificadores de assinaturas, então não é possível consultar a próxima cobrança individual.'''),
 'retirada': ('Retirada em loja', '''A retirada em loja é uma opção fictícia escolhida no checkout quando disponível. O cliente deve aguardar a confirmação de que o pedido está pronto antes de se deslocar. O prazo para buscar é de 3 dias corridos após essa confirmação. Se não puder comparecer, procure o atendimento para orientação, sem presumir cancelamento automático. O kit não inclui endereços de lojas, mapa, horários individuais ou disponibilidade por unidade. O assistente deve reconhecer essa ausência e encaminhar a consulta ao atendimento, sem inventar uma loja próxima. A retirada não altera as condições de troca, devolução e reembolso documentadas. Para acompanhar um pedido, informe seu número; o acesso é restrito ao cliente autenticado da sessão. Na retirada real, a conferência de identidade deve ocorrer por canal seguro, nunca enviando fotografia de documento ou senha pelo chat deste protótipo. A presença de estoque no catálogo geral não garante disponibilidade em uma unidade. Este ambiente não reserva produtos nem confirma uma retirada concluída. Para cancelamento, aplicam-se os estados descritos na RN04. Caso haja dúvida sobre comparecimento por terceiro, o kit não define autorização específica e o atendimento precisa analisar o caso.'''),
 'privacidade': ('Privacidade e dados pessoais', '''O assistente usa somente os dados necessários para responder à solicitação. A identidade do cliente vem da sessão confiável, definida na inicialização do ambiente de demonstração. Declarar outro identificador no texto não altera essa identidade. Cada consulta a pedidos verifica a titularidade antes de retornar detalhes. Não mostramos nome, endereço, e-mail, documento, itens ou situação de pedido pertencente a outra pessoa. Os dados deste projeto são sintéticos; os e-mails usam o domínio reservado example.invalid e os documentos têm rótulos explícitos de teste. O catálogo não contém dados pessoais. Os logs persistidos contêm eventos estruturados com rota, fontes, tempo e códigos de resultado, sem armazenar a mensagem original, identificador do cliente ou número do pedido. Essa minimização evita depender apenas de expressões regulares para mascarar dados. Conversas ficam apenas em memória durante a sessão e podem ser apagadas encerrando o processo. O protótipo não comprova conformidade jurídica completa com a LGPD e não substitui revisão especializada. Solicitações de acesso, correção ou exclusão de dados devem ser encaminhadas ao atendimento humano. Nunca informe senha, código temporário ou dados bancários completos ao assistente.'''),
 'atendimento': ('Canais e horários de atendimento', '''O atendimento humano fictício funciona de segunda a sexta, das 9h às 18h, no horário de Brasília, exceto feriados. O canal de demonstração é atendimento@example.invalid. Esse endereço é deliberadamente não entregável: não representa uma empresa real. Este protótipo orienta o encaminhamento, mas não envia mensagens, não abre chamados externos e não promete que uma pessoa já está conectada. Fora do horário, a solicitação deve aguardar o próximo período de atendimento. O assistente deve oferecer encaminhamento quando houver pedido explícito para falar com uma pessoa, reclamação grave ou pergunta de saúde animal. Casos de ameaça, fraude relatada, acidente ou dano relevante exigem atenção humana. Para saúde animal, o assistente não fornece diagnóstico, dosagem de medicamentos ou prescrição e orienta buscar um médico veterinário; em situação urgente, orienta procurar atendimento veterinário imediatamente. Dúvidas comuns de compra podem ser respondidas a partir das políticas disponíveis. Não há neste kit regras de garantia estendida ou programa de fidelidade. Nessas situações, o assistente declara não ter informação e oferece o canal humano. Ao pedir ajuda, evite expor dados pessoais desnecessários. Uma consulta comercial não substitui atendimento clínico ou emergência veterinária.'''),
}

def main():
    (ROOT / 'politicas').mkdir(parents=True, exist_ok=True)
    for slug, (title, body) in POLICIES.items():
        (ROOT / 'politicas' / f'{slug}.md').write_text(f'# {title}\n\n{body}\n', encoding='utf-8')
    products = []
    for i in range(1, 51):
        species = 'gato' if i % 2 == 0 else 'cao'
        category = ['racao', 'areia', 'brinquedo', 'acessorio', 'higiene'][(i-1) % 5]
        products.append(dict(SKU=f'SKU{i:03}', nome=f'Pet Aurora {category} {species} {"Plus" if i % 3 else "Premium"} {i}', categoria=category, especie=species, preco=f'{19+i*3}.90', estoque=0 if i % 7 == 0 else 5+i, descricao=f'{category} fictício para {species}. Linha Aurora para uso pet; consultar o rótulo.'))
    with (ROOT / 'catalogo.csv').open('w', encoding='utf-8', newline='') as f:
        w = csv.DictWriter(f, fieldnames=list(products[0])); w.writeheader(); w.writerows(products)
    states = ['Pago','Em separação','Enviado','Entregue','Entregue','Cancelado','Pago','Enviado','Entregue','Em separação']
    orders = [dict(numero=str(1001+i), cliente_id=f'cliente-{1+i%3}', status=s, regiao=['Sudeste','Sul','Nordeste','Norte','Centro-Oeste'][i%5], pagamento='Pix' if i%2 == 0 else 'Cartão', entregue_em=({3:'2026-10-25',4:'2026-10-10',8:'2026-09-20'}.get(i)), itens=[dict(sku=f'SKU{i+1:03}', quantidade=1)]) for i,s in enumerate(states)]
    (ROOT / 'pedidos.json').write_text(json.dumps(orders, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    (ROOT / 'clientes.json').write_text(json.dumps([dict(id=f'cliente-{i}', email=f'cliente{i}@example.invalid', documento=f'CPF-FICTICIO-{i:03}') for i in range(1,4)], indent=2)+'\n', encoding='utf-8')

if __name__ == '__main__':
    main()
